{
  "correction_rules": [
    "Bias correction: Model consistently underestimates prices in bullish sentiment periods (sentiment > 0.33), especially after recent spikes — adjust forecast upward by 1–3% for sentiment > 0.33.",
    "Lag correction: Model often lags true price movements by 1–3 days — apply a 1-day forward shift in forecast for sentiment-neutral or bullish periods.",
    "Overshoot correction: After sharp price spikes (e.g., >5% from prior day), model tends to overcorrect — reduce forecast by 1–2% in the next 2–3 days if sentiment remains flat or negative.",
    "Mean reversion: If model forecast is >10% above recent 7-day average, apply downward pressure of 0.5–1.5% per day until convergence with true trend.",
    "Horizon-specific: For 30-day forecasts, model underperforms in high volatility periods (sentiment > 0.33) — increase forecast volatility buffer by 10–20% to account for tail risk."
  ]
}
